"""Are trace classes generated by simple moves?  python3 tracemoves.py N j
Compares, on the j-sets with g > 0 (mirror NOT identified here):
  traces        number of distinct traces,
  shift-closure components of the graph T ~ T - x + (x+1) whenever the trace is equal,
  swap-closure  components of T ~ T - x + y (any x in T, y not in T) with equal trace.
If shift-closure == traces, a canonical representative (e.g. the lexicographically
smallest member) could be found by local moves, which is what a dense trace-indexed
storage would need (NOTES.txt section 4)."""
import sys
from common import tables, masks


def main():
    N = int(sys.argv[1])
    j = int(sys.argv[2])
    valid, g, f = tables(N)
    lm, rm = masks(N)
    pc = int.bit_count

    def trace(t):
        out = []
        x = t
        while x:
            b = x & -x
            p = b.bit_length() - 1
            x ^= b
            out.append((pc(t & lm[p]), pc(t & rm[p])))
        return tuple(out)

    sets = [s for s in range(1 << N) if pc(s) == j and g[s]]
    tr = {s: trace(s) for s in sets}
    par = {s: s for s in sets}

    def find(a):
        while par[a] != a:
            par[a] = par[par[a]]
            a = par[a]
        return a

    def union(a, b):
        a, b = find(a), find(b)
        if a != b:
            par[a] = b

    ntr = len(set(tr.values()))
    for s in sets:
        for p in range(N - 1):
            if s >> p & 1 and not s >> (p + 1) & 1:
                t = s ^ (1 << p) ^ (1 << (p + 1))
                if t in tr and tr[t] == tr[s]:
                    union(s, t)
    nshift = len({find(s) for s in sets})
    par = {s: s for s in sets}
    for s in sets:
        for p in range(N):
            if not s >> p & 1:
                continue
            for q in range(N):
                if s >> q & 1:
                    continue
                t = s ^ (1 << p) ^ (1 << q)
                if t in tr and tr[t] == tr[s]:
                    union(s, t)
    nswap = len({find(s) for s in sets})
    print('N=%d j=%d sets(g>0)=%d traces=%d shift-closure=%d swap-closure=%d' % (N, j, len(sets), ntr, nshift, nswap))


if __name__ == '__main__':
    main()
